const guildRanks=[{name:'Bronze',color:'#bd7b50',detail:'Burnished copper · Single frame'},{name:'Silver',color:'#aab3bf',detail:'Brushed cool steel · Matte graphite'},{name:'Gold',color:'#dbb14e',detail:'Warm gold alloy · Recessed inner frame'},{name:'Platinum',color:'#83cfda',detail:'Bright platinum · Petrol ceramic band'},{name:'Diamond',color:'#75e3fa',detail:'Platinum frame · Ice-crystal corner inlays'},{name:'Master',color:'#8c91ff',detail:'Reinforced black titanium · Broad indigo ceramic band'},{name:'Legend',color:'#168bff',detail:'Layered silver armor · XOX blue O and white dot'}];
function guildRankMeta(g){return !g?.isNew&&guildRanks.find(r=>r.name.toLowerCase()===String(g?.tier).toLowerCase())}
function guildRankIcon(g,size=24){const rank=guildRankMeta(g);return rank?`<img class="guild-rank-icon ${size>32?'guild-rank-material':''}" src="assets/rank-${rank.name.toLowerCase()}${size<=32?'-compact.svg':'-art.webp'}" width="${size}" height="${size}" alt="${rank.name} guild tier">`:''}
function guildRankChip(g){const rank=guildRankMeta(g);return rank?`<span class="guild-rank-chip" style="--rank-accent:${rank.color}">${guildRankIcon(g,26)}<span>${rank.name}</span></span>`:'<span class="guild-rank-chip unranked">Unranked</span>'}
function guildRankGuide(){return `<div class="guild-rank-guide"><span class="page-eyebrow">XOX GUILD RANKS · DESIGN PREVIEW</span><h2>Earn your place.<br>Wear your rank.</h2><p>One shield. Seven ranks. Increasing depth, material quality and XOX identity.</p><div class="guild-rank-gallery">${guildRanks.map((r,i)=>`<article style="--rank-accent:${r.color}"><small>0${i+1}</small>${guildRankIcon({tier:r.name},80)}<h3>${r.name}</h3><p>${r.detail}</p><div class="rank-small-preview"><span>${guildRankIcon({tier:r.name},20)}<small>20 px</small></span><span>${guildRankIcon({tier:r.name},24)}<small>24 px</small></span><span class="rank-monochrome">${guildRankIcon({tier:r.name},24)}<small>Shape</small></span></div></article>`).join('')}</div><div class="guild-rank-explanation"><strong>Guild tier and season placement are separate.</strong><p>Bronze → Legend is the guild progression system. #1, #2 and so on are positions on the season leaderboard. Promotion rules and reset conditions will be designed separately.</p></div><details class="guild-rank-art-study"><summary>View the material & silhouette concept study</summary><img src="assets/guild-ranks-concept.webp" alt="Seven proposed XOX guild badges, from bronze to legend, with one shared shield, copper, steel, gold, bright platinum, crystal inlays, reinforced Master armor and XOX-blue Legend" loading="lazy"><p>Approved shared-shield direction. Master has been strengthened in the production artwork above. Compact icons simplify these materials for the leaderboard.</p></details></div>`}
const rankCardBase=traderGuildCard;traderGuildCard=function(g){return rankCardBase(g).replace('<div class="trader-entry-state">',`<div class="guild-card-rank">${guildRankChip(g)}<small>GUILD TIER · DEMO</small></div><div class="trader-entry-state">`)};
const rankBoardBase=traderMemberBoard;traderMemberBoard=function(){const g=state.membership&&guildById(state.membership.id);let html=rankBoardBase();if(g)html=html.replace(`<h2>${escapeHtml(g.name)}</h2>`,`<h2>${escapeHtml(g.name)}</h2><div class="guild-member-rank">${guildRankChip(g)}<button class="text-button" data-rank-guide>Rank guide</button></div>`);return html};
const rankBannerBase=communityThemeBanner;communityThemeBanner=function(c,own=false){const g=guildById(c.id);return rankBannerBase(c,own).replace('<div class="community-banner-actions">',`<div class="guild-banner-rank">${guildRankChip(g)}<button class="text-button" data-rank-guide>Guild ranks ${arrow()}</button></div><div class="community-banner-actions">`)};
const rankRowsBase=climbRows;climbRows=function(){let html=rankRowsBase();for(const g of worldGuilds()){const label=g.id===state.membership?.id?'YOUR GUILD':g.members.toLocaleString()+' members';html=html.replace(`<small>${label}</small>`,`<small class="climb-team-rank">${guildRankIcon(g,20)}<span>${guildRankMeta(g)?.name||'Unranked'}${g.id===state.membership?.id?' · YOUR GUILD':''}</span></small>`)}return html};
const rankRailBase=climbRail;climbRail=function(){return rankRailBase().replace('<footer><span>', '<footer><button class="text-button rank-guide-link" data-rank-guide>Guild rank badges '+arrow()+'</button><span>')};
progression=function(g,preview){const current=guildRankMeta(g),index=current?guildRanks.findIndex(r=>r.name===current.name):-1,next=guildRanks[index+1];return `<section class="workspace-panel guild-rank-progression">${sectionTitle('Your guild rank','Progression preview · Rules to be confirmed')}<div class="guild-rank-current">${guildRankIcon(g,84)}<div><small>CURRENT GUILD TIER</small><h2>${current?.name||'Unranked'}</h2><p>${next?'Next tier · '+next.name:'Highest guild tier'}</p></div><button class="secondary" data-rank-guide>View all ranks ${arrow()}</button></div><div class="guild-rank-steps">${guildRanks.map((r,i)=>`<div class="${i===index?'current':''}">${guildRankIcon({tier:r.name},36)}<span>${r.name}</span></div>`).join('')}</div><p class="guild-rank-parameters">Promotion conditions, scoring and season resets remain adjustable. No live guild tier is changed by this prototype.</p></section>`};
const rankDashboardBase=dashboardOverview;dashboardOverview=function(g,preview){return rankDashboardBase(g,preview)+progression(g,preview)};
document.addEventListener('click',e=>{const target=e.target.closest('[data-rank-guide]');if(target){document.querySelector('.guild-more-nav')?.removeAttribute('open');open(guildRankGuide());return}const more=document.querySelector('.guild-more-nav');if(more&&(!more.contains(e.target)||e.target.closest('.guild-more-nav a,.guild-more-nav button')))more.removeAttribute('open')});
document.addEventListener('keydown',e=>{const more=document.querySelector('.guild-more-nav[open]');if(e.key==='Escape'&&more){more.removeAttribute('open');more.querySelector('summary')?.focus()}});
renderRoute(false);
